spec.expr:
sum(
  rate(
    vector_component_received_events_total{
      component_id="http_in"
    }[1m]
  )
) or vector(0)

(
  (
    sum(
      rate(
        kafka_server_brokertopicmetrics_messagesinpersec_topic{
          topic="test_topic"
        }[1m]
      )
    )
    or vector(0)
  )
  and on()
  (
    shireguard_config_active_broker{broker="kafka"} == 1
  )
)
or
(
  (
    sum(
      rate(
        redpanda_kafka_records_produced_total{
          redpanda_namespace="kafka",
          redpanda_topic="test_topic"
        }[1m]
      )
    )
    or vector(0)
  )
  and on()
  (
    shireguard_config_active_broker{broker="redpanda"} == 1
  )
)
